css:
@keyframes blink {
  50% {
    opacity: 0;
  }
}

@keyframes reveal {
  0%,
  60% {
    background: var(--color-accent-soft);
    box-shadow: 0 0 0 0.75rem var(--color-accent-soft);
  }
  to {
    background: transparent;
    box-shadow: 0 0 0 0.75rem transparent;
  }
}

@keyframes marker-sweep {
  to {
    background-size: 100% 100%;
  }
}

@keyframes marker-fade {
  from {
    opacity: 0;
  }
}

@keyframes page-out {
  to {
    opacity: 0;
  }
}

@keyframes page-in-forward {
  from {
    opacity: 0;
    translate: -1.5rem 0;
  }
}

@keyframes page-in-back {
  from {
    opacity: 0;
    translate: 1.5rem 0;
  }
}

@keyframes page-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes cover-content-in {
  0%,
  40% {
    opacity: 0;
  }
}

::view-transition-group(root) {
  animation-duration: 200ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

::view-transition-group(reader-page) {
  animation-duration: 200ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

::view-transition-old(reader-page) {
  animation-name: page-out;
  animation-duration: 90ms;
  animation-fill-mode: both;
}

:active-view-transition-type(forward)::view-transition-new(reader-page) {
  animation-name: page-in-forward;
  animation-delay: 40ms;
  animation-fill-mode: both;
}

:active-view-transition-type(back)::view-transition-new(reader-page) {
  animation-name: page-in-back;
  animation-delay: 40ms;
  animation-fill-mode: both;
}

::view-transition-group(page-counter) {
  animation-duration: 0s;
}

::view-transition-old(page-counter) {
  display: none;
}

::view-transition-new(page-counter) {
  animation: none;
}

::view-transition-group(book-cover) {
  animation-duration: 420ms;
  animation-timing-function: cubic-bezier(0.32, 0.72, 0, 1);
}

::view-transition-new(book-cover) {
  animation-name: cover-content-in;
  animation-duration: 420ms;
}

@media (prefers-reduced-motion: reduce) {
  :active-view-transition-type(forward)::view-transition-new(reader-page) {
    animation-name: page-fade-in;
  }

  :active-view-transition-type(back)::view-transition-new(reader-page) {
    animation-name: page-fade-in;
  }

  ::view-transition-group(book-cover) {
    animation-duration: 0s;
  }
}

